"use strict";(globalThis.webpackChunkgrc||=[]).push([[75161],{94324(e){e.exports=JSON.parse('{"citeKey":"chanchio2001protocoldesign","slug":"chanchio-2001-protocol-design-47be","title":"A Protocol Design for Communication State Transfer for Distributed Computing","authors":["K. Chanchio","X.-H. Sun"],"venue":"The 21st International Conference on Distributed Computing Systems (ICDCS 2001)","type":"Conference","entryType":"inproceedings","date":"April, 2001","year":2001,"era":"iit","month":4,"doi":"10.1109/icdsc.2001.919007","abstract":"This paper presents the design of a communication state transfer protocol to support process migration in a dynamic, distributed computing environment. In our design, pro- cesses in distributed computation communicate one another via message passing and are migration-enabled. Due to mo- bility, mechanisms to maintain reliability and correctness of data communication are needed. Following an event-based approach, such mechanisms are derived to handle various communication situations when a process migrates. These mechanisms collectively preserve the semantics of the com- munication and support efficient communication state trans- fer.","hasAbstract":true,"lede":"This paper presents the design of a communication state transfer protocol to support process migration in a dynamic, distributed computing environment.","links":{"pdf":"https://grc.iit.edu/papers/2001/chanchio-2001-protocol-design-47be.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);